config.code:
const rec = (input.records || [])[0];
if (!rec) return { ...input, hasClient: false };
const f = rec.fields || {};
return {
  ...input,
  hasClient: true,
  recordId: rec.id,
  businessName: f.Name || "",
  website: f.Website || "",
  contactEmail: f.Email || "",
  sentAt: new Date().toISOString()
};

